assert thumbFile.exists() : "Thumbnail file should exist";
assert thumbFile.getName().equals("thumbnail.temp_input.png") : "Thumbnail file name should match Rename strategy";

java.awt.image.BufferedImage thumbImage = javax.imageio.ImageIO.read(thumbFile);
assert thumbImage.getWidth() <= 50 && thumbImage.getHeight() <= 50 : "Thumbnail dimensions should be within 50x50";

System.out.println("__CHECK__ createThumbnailsAsCollection " + thumbnails.size() + "," + thumbFile.getName());

